res=[]
V={'a':a,'b':b,'c':c}
import itertools
exprs={}
for op,f in [('+',lambda x,z:x+z),('-',lambda x,z:x-z),('*',lambda x,z:x*z),('^',lambda x,z:x^z),('&',lambda x,z:x&z),('|',lambda x,z:x|z)]:
  for p,q in itertools.permutations('abc',2):
    for m in [None,32,16,8,4,2,3,5,7]:
      v=f(V[p],V[q]); 
      if m: v=v%m
      exprs[f'({p}{op}{q})%{m}']=v
for k,v in exprs.items():
  r=[q for q in 'abc' if q not in k][0] if len(set(k)&set('abc'))==2 else None
  for t in range(-5,40):
    for cmp in ['>','<','==']:
      for rhs_name,rhs in [('c',c),('a',a),('b',b),('k',t)]:
        if cmp=='==' and rhs_name!='k': pass
        pred = v>rhs+ (t if rhs_name!='k' else 0)*0 if cmp=='>' else (v<rhs if cmp=='<' else v==rhs)
        if rhs_name!='k' and t!=0: continue
        acc=(pred.astype(int)==y).mean(); res.append((max(acc,1-acc),k,cmp,rhs_name,t))
res.sort(reverse=True)
for r in res[:25]: print(r)
